const cityMediaPicker=document.createElement('input');cityMediaPicker.hidden=true;cityMediaPicker.type='file';cityMediaPicker.accept='image/*,video/mp4,video/webm';document.body.append(cityMediaPicker);function chooseCityMedia(){cityMediaPicker.value='';cityMediaPicker.click()}let cityURL=null;function attachCityMedia(file){if(cityURL)URL.revokeObjectURL(cityURL);cityURL=URL.createObjectURL(file);if(cityMedia instanceof HTMLVideoElement){cityMedia.pause();cityMedia.remove()}if(file.type.startsWith('video/')){const v=document.createElement('video');v.hidden=true;v.muted=true;v.loop=true;v.playsInline=true;v.preload='auto';v.src=cityURL;document.body.append(v);v.onloadeddata=()=>base._renderKey='';v.onseeked=()=>base._renderKey='';v.load();cityMedia=v}else{const im=new Image();im.onload=()=>base._renderKey='';im.src=cityURL;cityMedia=im}base._renderKey=''}cityMediaPicker.onchange=async()=>{const file=cityMediaPicker.files[0];if(!file)return;attachCityMedia(file);await saveAsset('city-media',file);seekCity(fx.cityDescent+2)};async function restoreCityMedia(){try{const db=await assetDB(),r=db.transaction('assets').objectStore('assets').get('city-media');r.onsuccess=()=>{if(r.result instanceof Blob)attachCityMedia(r.result);db.close()}}catch{}}
