const priorChessEditor=renderChessEditor;renderChessEditor=function(){priorChessEditor();const box=document.querySelector('#chessEditor');if(!box)return;const endpoints=document.createElement('details');endpoints.className='cameraEndpoints';endpoints.innerHTML='<summary>3D zoom · start and end views</summary><p class="sub">Orbit, pan and zoom in Edit 3D, then capture each endpoint. These replace the automatic camera path.</p><button class="pill wide" id="zoomStart">Set starting view from Edit 3D</button><button class="pill wide" id="zoomEnd">Set ending view from Edit 3D</button><label for="zoomEndTime">End view time (s)</label><input id="zoomEndTime" type="number" min="1" max="120" value="'+fx.chessDuration+'">';box.append(endpoints);for(const [id,start]of [['zoomStart',true],['zoomEnd',false]])endpoints.querySelector('#'+id).onclick=()=>{if(!chessEditing){setChessMode(true);return}const time=start?0:+endpoints.querySelector('#zoomEndTime').value,view=chessEngine.getCamera();fx.chessCameraKeys||=[];fx.chessCameraKeys=fx.chessCameraKeys.filter(k=>Math.abs(k.time-time)>.01);fx.chessCameraKeys.push({time,...view,ease:'smooth'});fx.chessCameraKeys.sort((a,b)=>a.time-b.time);if(time>fx.chessDuration){fx.chessDuration=time;syncDuration()}saveEffects();endpoints.querySelector('#'+id).textContent=start?'Starting view saved':'Ending view saved'}};
