const cityMarkPicker=document.createElement('input');cityMarkPicker.hidden=true;cityMarkPicker.type='file';cityMarkPicker.accept='image/*';document.body.append(cityMarkPicker);let cityMarkTarget='logo';function chooseCityMark(key){cityMarkTarget=key;cityMarkPicker.value='';cityMarkPicker.click()}function attachCityMark(key,file){const im=new Image();im.onload=()=>base._renderKey='';im.src=URL.createObjectURL(file);if(key==='logo')cityLogoImage=im;else cityCatImage=im}cityMarkPicker.onchange=async()=>{const file=cityMarkPicker.files[0];if(!file)return;attachCityMark(cityMarkTarget,file);await saveAsset('city-mark-'+cityMarkTarget,file)};async function restoreCityMarks(){try{const db=await assetDB();for(const key of ['logo','cat']){const r=db.transaction('assets').objectStore('assets').get('city-mark-'+key);r.onsuccess=()=>{if(r.result instanceof Blob)attachCityMark(key,r.result)}}}catch{}}
